// Extract incoming webhook payload and headers
const webhookData = $('Website Webhook').first().json;
const config = $('Config & Credentials').first().json;

const headers = webhookData.headers || {};
const body = webhookData.body || webhookData;

// 1. Validate Event Type
const supportedEvents = [
  'ORDER_PLACED',
  'ORDER_CONFIRMED',
  'ORDER_PROCESSING',
  'ORDER_PACKED',
  'ORDER_SHIPPED',
  'ORDER_DELIVERED',
  'ORDER_CANCELLED',
  'WHOLESALE_ENQUIRY_CREATED'
];

const eventType = body.event_type || headers['x-webhook-event'];
const isValidEvent = supportedEvents.includes(eventType);

// 2. HMAC-SHA256 Signature Verification (if enabled/configured)
let isAuthorized = true;
let authMessage = 'Signature verification passed or bypassed';

const signatureHeader = headers['x-webhook-signature-256'] || headers['X-Webhook-Signature-256'];
const secret = config.WEBHOOK_SECRET;
const requireHmac = config.REQUIRE_HMAC_SIGNATURE === true || (secret && secret !== 'YOUR_WEBHOOK_SECRET_HERE');

if (requireHmac) {
  if (!signatureHeader) {
    isAuthorized = false;
    authMessage = 'Missing X-Webhook-Signature-256 header';
  } else {
    try {
      const crypto = require('crypto');
      const rawPayload = typeof body === 'string' ? body : JSON.stringify(body);
      const expectedSignature = 'sha256=' + crypto.createHmac('sha256', secret).update(rawPayload).digest('hex');

      if (signatureHeader !== expectedSignature) {
        isAuthorized = false;
        authMessage = 'Signature mismatch';
      }
    } catch (err) {
      isAuthorized = false;
      authMessage = 'Crypto verification error: ' + err.message;
    }
  }
}

// 3. Phone Number Normalization Helper
function normalizePhone(raw) {
  if (!raw) return '';
  let cleaned = String(raw).replace(/\D/g, '');
  if (cleaned.length === 10) {
    cleaned = '91' + cleaned; // Standard Indian 10-digit mobile
  }
  return cleaned;
}

// 4. Idempotency & Deduplication Control
// Uses n8n workflow static data to store processed keys for 24 hours
const staticData = $getWorkflowStaticData('global');
staticData.processedEvents = staticData.processedEvents || {};

const now = Date.now();
const RETENTION_MS = 24 * 60 * 60 * 1000;

// Cleanup expired keys
for (const [key, timestamp] of Object.entries(staticData.processedEvents)) {
  if (now - timestamp > RETENTION_MS) {
    delete staticData.processedEvents[key];
  }
}

const uniqueEntityId = body.order_id || body.enquiry_id || 'unknown';
const deduplicationKey = body.idempotency_key || `${uniqueEntityId}:${eventType}`;

let isDuplicate = false;
if (deduplicationKey && staticData.processedEvents[deduplicationKey]) {
  isDuplicate = true;
} else if (isAuthorized && isValidEvent && deduplicationKey) {
  staticData.processedEvents[deduplicationKey] = now;
}

// 5. Build Normalized Payload
return [{
  json: {
    is_authorized: isAuthorized,
    is_duplicate: isDuplicate,
    is_valid_event: isValidEvent,
    auth_message: authMessage,
    deduplication_key: deduplicationKey,
    event_type: eventType,

    // Customer / Recipient Data
    customer_name: body.customer_name || 'Valued Merchant',
    customer_phone: normalizePhone(body.customer_phone),
    business_name: body.business_name || null,
    customer_type: body.customer_type || 'Retail Merchant',

    // Order Specific Fields
    order_id: body.order_id || null,
    order_number: body.order_number || body.order_id || 'N/A',
    order_status: body.order_status || 'Pending',
    total_pieces: Number(body.total_pieces || 0),
    subtotal: Number(body.subtotal || 0),
    delivery_charge: Number(body.delivery_charge || 0),
    total_amount: Number(body.total_amount || 0),
    payment_status: body.payment_status || 'Pending',
    tracking_number: body.tracking_number || null,
    lr_number: body.lr_number || null,
    transporter_name: body.transporter_name || null,
    shipped_at: body.shipped_at || null,
    delivered_at: body.delivered_at || null,

    // Wholesale Enquiry Specific Fields
    enquiry_id: body.enquiry_id || null,
    enquiry_message: body.enquiry_message || '',

    // System Meta & Config Passthrough
    admin_whatsapp_number: normalizePhone(config.ADMIN_WHATSAPP_NUMBER || '919440472939'),
    meta_access_token: config.META_WHATSAPP_ACCESS_TOKEN,
    meta_phone_number_id: config.META_WHATSAPP_PHONE_NUMBER_ID,
    meta_waba_id: config.META_WHATSAPP_BUSINESS_ACCOUNT_ID,

    // Template Names Mapping
    template_order_placed: config.TEMPLATE_ORDER_PLACED,
    template_order_confirmed: config.TEMPLATE_ORDER_CONFIRMED,
    template_order_processing: config.TEMPLATE_ORDER_PROCESSING,
    template_order_packed: config.TEMPLATE_ORDER_PACKED,
    template_order_shipped: config.TEMPLATE_ORDER_SHIPPED,
    template_order_delivered: config.TEMPLATE_ORDER_DELIVERED,
    template_order_cancelled: config.TEMPLATE_ORDER_CANCELLED,
    template_wholesale_enquiry: config.TEMPLATE_WHOLESALE_ENQUIRY,

    timestamp: body.created_at || new Date().toISOString()
  }
}];

const item = $input.first().json;

return [{
  json: {
    status: 'DROPPED',
    reason:
      !item.is_authorized ? `Authorization Failed: ${item.auth_message}` :
      item.is_duplicate ? `Duplicate Event Suppressed: ${item.deduplication_key}` :
      !item.is_valid_event ? `Unsupported Event Type: ${item.event_type}` :
      'Unknown',
    event_type: item.event_type,
    deduplication_key: item.deduplication_key,
    timestamp: new Date().toISOString()
  }
}];

const d = $input.first().json;

const metaPayload = {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: d.customer_phone,
  type: 'template',
  template: {
    name: d.template_order_placed,
    language: { code: 'en' },
    components: [
      {
        type: 'body',
        parameters: [
          { type: 'text', text: d.customer_name },
          { type: 'text', text: d.order_number },
          { type: 'text', text: `${d.total_pieces} pcs` },
          { type: 'text', text: `₹${d.total_amount.toLocaleString('en-IN')}` },
          { type: 'text', text: d.payment_status }
        ]
      }
    ]
  }
};

return [{
  json: {
    ...d,
    recipient_phone: d.customer_phone,
    template_name: d.template_order_placed,
    meta_payload: metaPayload
  }
}];

