const response = $input.first().json;

// Look back to previous node payload
let sourceData = {};
try {
  sourceData = $('Send Meta WhatsApp Message').first().json || {};
} catch (e) {}

const isError = Boolean(
  response.error ||
  response.error_data ||
  (response.statusCode && response.statusCode >= 400)
);

if (isError) {
  const errObj = response.error || response;
  return [{
    json: {
      status: 'FAILED',
      event_type: sourceData.event_type || 'UNKNOWN',
      order_id: sourceData.order_id || null,
      enquiry_id: sourceData.enquiry_id || null,
      recipient: sourceData.recipient_phone || 'UNKNOWN',
      template_name: sourceData.template_name || 'UNKNOWN',
      meta_error_message: errObj.message || 'WhatsApp Cloud API call returned an error',
      meta_error_code: errObj.code || null,
      error_details: errObj,
      timestamp: new Date().toISOString()
    }
  }];
}

return [{
